CREATE TABLE IF NOT EXISTS public.admin_list_preferences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, list_key text NOT NULL, name text NOT NULL, settings jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,list_key,name));
GRANT SELECT ON public.admin_list_preferences TO authenticated;
GRANT ALL ON public.admin_list_preferences TO service_role;
ALTER TABLE public.admin_list_preferences ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='admin_list_preferences' AND policyname='own_list_preferences') THEN CREATE POLICY own_list_preferences ON public.admin_list_preferences FOR SELECT TO authenticated USING(user_id=auth.uid()); END IF; END $$;
CREATE TABLE IF NOT EXISTS public.admin_export_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, actor_role text NOT NULL, list_key text NOT NULL, format text NOT NULL CHECK(format IN ('csv','xlsx')), scope jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','generated','failed')), row_count integer CHECK(row_count>=0), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
GRANT SELECT ON public.admin_export_requests TO authenticated;
GRANT ALL ON public.admin_export_requests TO service_role;
ALTER TABLE public.admin_export_requests ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='admin_export_requests' AND policyname='own_export_requests') THEN CREATE POLICY own_export_requests ON public.admin_export_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')); END IF; END $$;
CREATE OR REPLACE FUNCTION public.save_admin_list_preferences(_list text,_name text,_settings jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.admin_list_preferences; old_row jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'يجب تسجيل الدخول'; END IF; IF length(trim(_name)) NOT BETWEEN 1 AND 60 OR length(_list)>80 OR octet_length(_settings::text)>16000 OR jsonb_typeof(_settings)<>'object' THEN RAISE EXCEPTION 'تفضيلات غير صالحة'; END IF; SELECT to_jsonb(p) INTO old_row FROM public.admin_list_preferences p WHERE user_id=auth.uid() AND list_key=_list AND name=trim(_name); INSERT INTO public.admin_list_preferences(user_id,list_key,name,settings) VALUES(auth.uid(),_list,trim(_name),_settings) ON CONFLICT(user_id,list_key,name) DO UPDATE SET settings=EXCLUDED.settings,updated_at=now() RETURNING * INTO r; PERFORM public._safety_audit('SAVE_LIST_PREFERENCES','admin_list_preferences',r.id::text,old_row,to_jsonb(r),'حفظ تفضيلات عرض القائمة'); RETURN r.id; END $$;
CREATE OR REPLACE FUNCTION public.request_admin_export(_list text,_format text,_scope jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.admin_export_requests; role_name text; permitted boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'يجب تسجيل الدخول'; END IF; IF _list NOT IN ('units','parties','contracts','receipts','installments','bookings','opportunities','tenants','tenant_accounts','paid_tenants','collections_report','leads','interested_customers','audit_log','access_log','activities','marketing_campaigns','unit_status_backfill_review','units_incomplete','payment_plans','receipt_reconciliation','receipt_legacy_sources','leasing_holds') OR _format NOT IN ('csv','xlsx') OR octet_length(_scope::text)>16000 THEN RAISE EXCEPTION 'نوع تصدير غير مسموح'; END IF; permitted:=public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'); IF _list IN ('audit_log','access_log','marketing_campaigns') THEN permitted:=public.has_role(auth.uid(),'admin'); ELSIF _list IN ('contracts','receipts','installments','payment_plans','receipt_reconciliation','receipt_legacy_sources') THEN permitted:=public.finance_can_read(); ELSIF _list='opportunities' THEN permitted:=permitted OR public.has_role(auth.uid(),'leasing_manager') OR public.has_role(auth.uid(),'sales_agent'); ELSIF _list='leasing_holds' THEN permitted:=public.has_role(auth.uid(),'leasing_manager'); END IF; IF NOT permitted THEN RAISE EXCEPTION 'غير مسموح لك بتصدير هذا التقرير'; END IF; SELECT role::text INTO role_name FROM public.user_roles WHERE user_id=auth.uid() AND is_active ORDER BY CASE role WHEN 'admin' THEN 0 WHEN 'manager' THEN 1 ELSE 2 END LIMIT 1; INSERT INTO public.admin_export_requests(user_id,actor_role,list_key,format,scope) VALUES(auth.uid(),role_name,_list,_format,_scope) RETURNING * INTO r; PERFORM public._safety_audit('EXPORT_REQUESTED','admin_export_requests',r.id::text,NULL,to_jsonb(r),'طلب تصدير محلي حسب الصلاحية'); RETURN r.id; END $$;
CREATE OR REPLACE FUNCTION public.complete_admin_export(_id uuid,_status text,_count integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.admin_export_requests; old_row jsonb; BEGIN SELECT * INTO r FROM public.admin_export_requests WHERE id=_id AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'طلب التصدير غير متاح'; END IF; IF r.status<>'requested' OR _status NOT IN ('generated','failed') OR _count<0 THEN RAISE EXCEPTION 'انتقال تصدير غير صالح'; END IF; old_row:=to_jsonb(r); UPDATE public.admin_export_requests SET status=_status,row_count=_count,completed_at=now() WHERE id=_id RETURNING * INTO r; PERFORM public._safety_audit('EXPORT_'||upper(_status),'admin_export_requests',r.id::text,old_row,to_jsonb(r),'تسجيل نتيجة إنشاء الملف محليًا دون ادعاء حفظه'); END $$;
REVOKE ALL ON FUNCTION public.save_admin_list_preferences(text,text,jsonb), public.request_admin_export(text,text,jsonb), public.complete_admin_export(uuid,text,integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_admin_list_preferences(text,text,jsonb), public.request_admin_export(text,text,jsonb), public.complete_admin_export(uuid,text,integer) TO authenticated;
SELECT to_regclass('public.admin_list_preferences') IS NOT NULL AS preferences_ready,to_regclass('public.admin_export_requests') IS NOT NULL AS exports_ready,has_table_privilege('authenticated','public.admin_list_preferences','INSERT') AS direct_write_must_be_false;